import { getEnabledElementByViewportId } from '@cornerstonejs/core';
import { SegmentationRepresentations } from '../../../enums/index.js';
import { getSegmentationRepresentations } from '../../../stateManagement/segmentation/getSegmentationRepresentation.js';
import getViewportLabelmapRenderMode from '../../../stateManagement/segmentation/helpers/getViewportLabelmapRenderMode.js';
import { syncStackLabelmapActors } from '../../../tools/displayTools/Labelmap/syncStackLabelmapActors.js';
export function performStackLabelmapUpdate({ viewportIds, segmentationId, }) {
    viewportIds.forEach((viewportId) => {
        let representations = getSegmentationRepresentations(viewportId, {
            segmentationId,
        });
        representations = representations.filter((representation) => representation.type === SegmentationRepresentations.Labelmap);
        representations.forEach((representation) => {
            if (representation.segmentationId !== segmentationId) {
                return;
            }
            const enabledElement = getEnabledElementByViewportId(viewportId);
            if (!enabledElement) {
                return;
            }
            const { viewport } = enabledElement;
            if (getViewportLabelmapRenderMode(viewport) !== 'image') {
                return;
            }
            if (typeof viewport
                .getCurrentImageId !== 'function') {
                return;
            }
            syncStackLabelmapActors(viewport, segmentationId);
        });
    });
}
